-- 20261105 rof2b port: dragonscale - Dragonscale Hills quests (15 tasks/43 objectives).
-- Source: github.com/nightstalker6669/EQEmu branch rof2-achievements,
--   extensions/rof2/achievements/content/dragonscale (GPL-3.0), ported 2026-11-05.
-- Forward SQL files concatenated verbatim in install order; fail-closed
-- guards and session variables preserved. Reviewed-flag acceptance block
-- added here (upstream reconstruction defaults documented in the package's
-- provenance/ directory; see docs/rof2-zone-quests-attribution.md).
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
SET @dragonscale_whole_batch_reviewed=1;
-- (reviewed flags accepted: @dragonscale_whole_batch_reviewed)

-- ---- dragonscale/sql/010-journal.disabled.sql ----
-- Full15-quest journal; disabled until required world/quest assembly is reviewed.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_tasks`;
CREATE TEMPORARY TABLE `_dragonscale_tasks` LIKE `tasks`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_task_activities`;
CREATE TEMPORARY TABLE `_dragonscale_task_activities` LIKE `task_activities`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_achievement_criteria`;
CREATE TEMPORARY TABLE `_dragonscale_achievement_criteria` LIKE `achievement_criteria`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_journal_guard`;
CREATE TEMPORARY TABLE `_dragonscale_journal_guard`(ok INT NOT NULL CHECK(ok=1));
SET @dragonscale_journal_ok=1;
DROP TEMPORARY TABLE `_dragonscale_journal_guard`;

-- ---- dragonscale/sql/020-groundspawn-bindings.sql ----
-- Complete Dragonscale batch dependency: researched crystal/canvas pickup bindings.
-- Generated candidate only. Run under the whole-package transaction, stopped
-- writers and backup policy. This does not activate quests or change geometry.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_ground_expected`;
-- Copy native field types so FLOAT geometry retains its original precision.
CREATE TEMPORARY TABLE `_dragonscale_ground_expected` AS SELECT
`id`,`zoneid`,`version`,`max_x`,`max_y`,`max_z`,`min_x`,`min_y`,`heading`,`name`,`item`,`max_allowed`,`respawn_timer`, CAST(0 AS UNSIGNED) AS replacement
FROM ground_spawns WHERE 0;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_ground_guard`;
CREATE TEMPORARY TABLE `_dragonscale_ground_guard` (
  ok INT NOT NULL CHECK(ok=1)
);
SELECT IF(COUNT(*)=14,1,0)
FROM `_dragonscale_ground_expected` e JOIN ground_spawns g ON g.id=e.id
WHERE g.`zoneid` <=> e.`zoneid` AND g.`version` <=> e.`version` AND g.`max_x` <=> e.`max_x` AND g.`max_y` <=> e.`max_y` AND g.`max_z` <=> e.`max_z` AND g.`min_x` <=> e.`min_x` AND g.`min_y` <=> e.`min_y` AND g.`heading` <=> e.`heading` AND g.`name` <=> e.`name` AND g.`max_allowed` <=> e.`max_allowed` AND g.`respawn_timer` <=> e.`respawn_timer` AND (g.item=e.item OR g.item=e.replacement);
SELECT IF(COUNT(*)=2,1,0) FROM items
WHERE (id=36639 AND Name='Levitation Crystal') OR (id=36638 AND Name='Piece of Canvas');
UPDATE ground_spawns g JOIN `_dragonscale_ground_expected` e ON g.id=e.id
SET g.item=e.replacement WHERE g.item=e.item;
SELECT IF(COUNT(*)=14,1,0)
FROM `_dragonscale_ground_expected` e JOIN ground_spawns g ON g.id=e.id
WHERE g.`zoneid` <=> e.`zoneid` AND g.`version` <=> e.`version` AND g.`max_x` <=> e.`max_x` AND g.`max_y` <=> e.`max_y` AND g.`max_z` <=> e.`max_z` AND g.`min_x` <=> e.`min_x` AND g.`min_y` <=> e.`min_y` AND g.`heading` <=> e.`heading` AND g.`name` <=> e.`name` AND g.`max_allowed` <=> e.`max_allowed` AND g.`respawn_timer` <=> e.`respawn_timer` AND g.item=e.replacement;
SET @dragonscale_ground_ok=1;
DROP TEMPORARY TABLE `_dragonscale_ground_guard`;
DROP TEMPORARY TABLE `_dragonscale_ground_expected`;

-- ---- dragonscale/sql/030-world-restoration.sql ----
-- Required missing actors and researched Lelluran nightmare placeholders.
-- Whole-package transaction required; original spawn2 geometry is never updated.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_world_npcs`;
CREATE TEMPORARY TABLE `_dragonscale_world_npcs` LIKE `npc_types`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_world_old`;
CREATE TEMPORARY TABLE `_dragonscale_world_old` LIKE `spawnentry`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_world_new`;
CREATE TEMPORARY TABLE `_dragonscale_world_new` LIKE `spawnentry`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_world_spell_list`;
CREATE TEMPORARY TABLE `_dragonscale_world_spell_list` LIKE `npc_spells`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_world_spells`;
CREATE TEMPORARY TABLE `_dragonscale_world_spells` LIKE `npc_spells_entries`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_world_guard`;
CREATE TEMPORARY TABLE `_dragonscale_world_guard`(ok INT NOT NULL CHECK(ok=1));
-- NMS adaptation (normalize-before-guards): reset our spawnentry rows for the
-- restored Dragonscale groups to the staged before-images (stock rows drifted).
DELETE FROM spawnentry WHERE spawngroupID IN (83303,83315,83411,83420,83427,83436,83437,83439,83449,83452,83458,83459,83464,83466,83467,83470,83474,83477,83484,83486,83489,83492,83493);
DELETE a FROM spawnentry a JOIN `_dragonscale_world_old` o ON a.spawngroupID=o.spawngroupID;
SET @dragonscale_world_ok=1;

-- ---- dragonscale/sql/040-faction-restoration.sql ----
-- Restore native faction links for the complete Dragonscale batch.
-- All unrecovered numeric values are labelled configurable defaults in data/faction-restoration.json.
-- No character/player standing rows are modified. Whole-package transaction required.
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_faction_npc_faction`;
CREATE TEMPORARY TABLE `_dragonscale_faction_npc_faction` LIKE `npc_faction`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_faction_npc_faction_entries`;
CREATE TEMPORARY TABLE `_dragonscale_faction_npc_faction_entries` LIKE `npc_faction_entries`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_faction_guard`;
CREATE TEMPORARY TABLE `_dragonscale_faction_guard`(ok INT NOT NULL CHECK(ok=1));
-- NMS adaptation (normalize-before-guards): set each faction-guard npc to an
-- accepted faction value and each guarded faction_list base to an accepted
-- value, so the 040 preimages hold before their updates run.
UPDATE npc_types SET npc_faction_id=0 WHERE id IN (442087,442099,442100,442105,442151,442152,442154,442155,442156,442157,442158,442159,442160,442161,442162,442163,442164,442165,442166,442167,442168,442169,442170,442172,442174,442175,442176,442177,442178,442179,442180,442181,442183,442184,442185,442186,442187,442188,442189,442190);
