INSERT INTO `npc_faction`(`id`,`name`,`primaryfaction`,`ignore_primary_assist`) SELECT e.`id`,e.`name`,e.`primaryfaction`,e.`ignore_primary_assist` FROM `_dragonscale_faction_npc_faction` e WHERE NOT EXISTS(SELECT 1 FROM `npc_faction` a WHERE a.`id`<=>e.`id`);
INSERT INTO `npc_faction_entries`(`npc_faction_id`,`faction_id`,`value`,`npc_value`,`temp`) SELECT e.`npc_faction_id`,e.`faction_id`,e.`value`,e.`npc_value`,e.`temp` FROM `_dragonscale_faction_npc_faction_entries` e WHERE NOT EXISTS(SELECT 1 FROM `npc_faction_entries` a WHERE a.`npc_faction_id`<=>e.`npc_faction_id` AND a.`faction_id`<=>e.`faction_id`);
INSERT INTO npc_types SELECT * FROM `_dragonscale_world_npcs`;
